commit 2ce0d7ab7c9ce5fab435008cf9637cadf07406fe
Author: Philip Withnall <withnall@endlessm.com>
Date:   Tue Jul 30 14:37:48 2019 +0100

    gdatetime: Avoid an assertion failure when parsing some ISO 8601 dates

    Some malformed ISO 8601 date/time strings were causing an assertion
    failure when passed to `g_date_time_new_from_iso8601()`, due to a
    mismatch between the bounds checking of timezone offsets in `GDateTime`
    and `GTimeZone`. Fix that and add a unit test for it.

    (Trivial backport of !1017.)

    oss-fuzz#16101

    Signed-off-by: Philip Withnall <withnall@endlessm.com>

diff --git a/glib/gdatetime.c b/glib/gdatetime.c
index 8abf45a87..7c94adf56 100644
--- a/glib/gdatetime.c
+++ b/glib/gdatetime.c
@@ -1296,122 +1296,128 @@ parse_iso8601_date (const gchar *text, gsize length,
           !get_iso8601_int (text + 4, 3, &ordinal_day))
         return NULL;
       return g_date_time_new_ordinal (tz, year, ordinal_day, hour, minute, seconds);
     }
   else
     return FALSE;
 }

 static GTimeZone *
 parse_iso8601_timezone (const gchar *text, gsize length, gssize *tz_offset)
 {
   gint i, tz_length, offset_sign = 1, offset_hours, offset_minutes;
   GTimeZone *tz;

   /* UTC uses Z suffix  */
   if (length > 0 && text[length - 1] == 'Z')
     {
       *tz_offset = length - 1;
       return g_time_zone_new_utc ();
     }

   /* Look for '+' or '-' of offset */
   for (i = length - 1; i >= 0; i--)
     if (text[i] == '+' || text[i] == '-')
       {
         offset_sign = text[i] == '-' ? -1 : 1;
         break;
       }
   if (i < 0)
     return NULL;
   tz_length = length - i;

   /* +hh:mm or -hh:mm */
   if (tz_length == 6 && text[i+3] == ':')
     {
       if (!get_iso8601_int (text + i + 1, 2, &offset_hours) ||
           !get_iso8601_int (text + i + 4, 2, &offset_minutes))
         return NULL;
     }
   /* +hhmm or -hhmm */
   else if (tz_length == 5)
     {
       if (!get_iso8601_int (text + i + 1, 2, &offset_hours) ||
           !get_iso8601_int (text + i + 3, 2, &offset_minutes))
         return NULL;
     }
   /* +hh or -hh */
   else if (tz_length == 3)
     {
       if (!get_iso8601_int (text + i + 1, 2, &offset_hours))
         return NULL;
       offset_minutes = 0;
     }
   else
     return NULL;

   *tz_offset = i;
   tz = g_time_zone_new (text + i);

   /* Double-check that the GTimeZone matches our interpretation of the timezone.
-   * Failure would indicate a bug either here of in the GTimeZone code. */
-  g_assert (g_time_zone_get_offset (tz, 0) == offset_sign * (offset_hours * 3600 + offset_minutes * 60));
+   * This can fail because our interpretation is less strict than (for example)
+   * parse_time() in gtimezone.c, which restricts the range of the parsed
+   * integers. */
+  if (g_time_zone_get_offset (tz, 0) != offset_sign * (offset_hours * 3600 + offset_minutes * 60))
+    {
+      g_time_zone_unref (tz);
+      return NULL;
+    }

   return tz;
 }

 static gboolean
 parse_iso8601_time (const gchar *text, gsize length,
                     gint *hour, gint *minute, gdouble *seconds, GTimeZone **tz)
 {
   gssize tz_offset = -1;

   /* Check for timezone suffix */
   *tz = parse_iso8601_timezone (text, length, &tz_offset);
   if (tz_offset >= 0)
     length = tz_offset;

   /* hh:mm:ss(.sss) */
   if (length >= 8 && text[2] == ':' && text[5] == ':')
     {
       return get_iso8601_int (text, 2, hour) &&
              get_iso8601_int (text + 3, 2, minute) &&
              get_iso8601_seconds (text + 6, length - 6, seconds);
     }
   /* hhmmss(.sss) */
   else if (length >= 6)
     {
       return get_iso8601_int (text, 2, hour) &&
              get_iso8601_int (text + 2, 2, minute) &&
              get_iso8601_seconds (text + 4, length - 4, seconds);
     }
   else
     return FALSE;
 }

 /**
  * g_date_time_new_from_iso8601:
  * @text: an ISO 8601 formatted time string.
  * @default_tz: (nullable): a #GTimeZone to use if the text doesn't contain a
  *                          timezone, or %NULL.
  *
  * Creates a #GDateTime corresponding to the given
  * [ISO 8601 formatted string](https://en.wikipedia.org/wiki/ISO_8601)
  * @text. ISO 8601 strings of the form <date><sep><time><tz> are supported.
  *
  * <sep> is the separator and can be either 'T', 't' or ' '.
  *
  * <date> is in the form:
  *
  * - `YYYY-MM-DD` - Year/month/day, e.g. 2016-08-24.
  * - `YYYYMMDD` - Same as above without dividers.
  * - `YYYY-DDD` - Ordinal day where DDD is from 001 to 366, e.g. 2016-237.
  * - `YYYYDDD` - Same as above without dividers.
  * - `YYYY-Www-D` - Week day where ww is from 01 to 52 and D from 1-7,
  *   e.g. 2016-W34-3.
  * - `YYYYWwwD` - Same as above without dividers.
  *
  * <time> is in the form:
  *
  * - `hh:mm:ss(.sss)` - Hours, minutes, seconds (subseconds), e.g. 22:10:42.123.
  * - `hhmmss(.sss)` - Same as above without dividers.
  *
