Author: Bastien Nocera <hadess@hadess.net>
Date:   Tue Nov 12 12:59:17 2019 +0100

    gdatetime: Handle leap seconds in ISO8601 dates

    GDateTime doesn't handle leap seconds, so just round these down to
    the previous second.

    (Cherry-pick had minor conflicts in the documentation.)

    https://gitlab.gnome.org/GNOME/glib/issues/1938

diff --git a/glib/gdatetime.c b/glib/gdatetime.c
index 3be4eba3d..f8bf31c43 100644
--- a/glib/gdatetime.c
+++ b/glib/gdatetime.c
@@ -1137,120 +1137,125 @@ G_GNUC_END_IGNORE_DEPRECATIONS
  * Deprecated: 2.62: #GTimeVal is not year-2038-safe. Use
  *    g_date_time_new_from_unix_utc() instead.
  **/
 G_GNUC_BEGIN_IGNORE_DEPRECATIONS
 GDateTime *
 g_date_time_new_from_timeval_utc (const GTimeVal *tv)
 {
   GDateTime *datetime;
   GTimeZone *utc;

   utc = g_time_zone_new_utc ();
   datetime = g_date_time_new_from_timeval (utc, tv);
   g_time_zone_unref (utc);

   return datetime;
 }
 G_GNUC_END_IGNORE_DEPRECATIONS

 /* Parse integers in the form d (week days), dd (hours etc), ddd (ordinal days) or dddd (years) */
 static gboolean
 get_iso8601_int (const gchar *text, gsize length, gint *value)
 {
   gsize i;
   guint v = 0;

   if (length < 1 || length > 4)
     return FALSE;

   for (i = 0; i < length; i++)
     {
       const gchar c = text[i];
       if (c < '0' || c > '9')
         return FALSE;
